Add `Current state`, `implementation details`, `acceptance criteria` for `design/feature_descriptions/F_166_improve_input_and_bottom_row_on_action_popup.md`.&#x20;
update the field `status` in the markdown feature description file to `ready for implementation`.

Read all referenced files before you begin except `agents` files. it is possible that the file is not yet written. &#x20;
Ask any question if something is ambiguous or not yet clear.
Be brief, but never compress away the subject, timing, or causal chain. Define ambiguous technical phrases. use $caveman skill.

Do not stage or commit changes. You have no need for get at this time.

import { Box, IconButton, Stack, Tooltip, Typography, useMediaQuery, useTheme } from '@mui/material'
import ArrowCollapseVertical from 'mdi-material-ui/ArrowCollapseVertical'
import ArrowExpandVertical from 'mdi-material-ui/ArrowExpandVertical'
import Close from 'mdi-material-ui/Close'
import { useMemo } from 'react'
import { actionContextIdentity, type ActionContext } from '../../../../data/action_context'
import type { ActionDefinition } from '../../../../data/action_types'
import { worktreeService } from '../../../../services/project/worktree_service'
import {
    actionRunSettingsService,
    createSessionActionRunSettingsStore,
} from '../../../../services/actions/action_run_settings_service'
import { ResizablePopper } from '../../../resizable_popper'
import type { WorktreeAssignmentTarget } from '../../../worktree_selector'
import { ActionAgentApprovals } from '../../agent/action_agent_approvals'
import { ActionAgentInteractionVisibility } from '../../agent/action_agent_interaction_visibility'
import { ActionAgentPromptOwner } from '../../agent/action_agent_prompt_owner'
import { ActionAgentQuestionOwner } from '../../agent/action_agent_question_owner'
import { ActionAgentSelectorsOwner } from '../../agent/action_agent_selectors_owner'
import { ActionConversationChatOwner } from '../../conversation/action_conversation_chat_owner'
import { ActionConversationPickerOwner } from '../../conversation/action_conversation_picker_owner'
import { ActionConversationStore } from '../../conversation/action_conversation_store'
import { ActionHistoryStore } from '../state/action_history_store'
import { ActionLogErrorOwner } from '../../conversation/action_log_error_owner'
import { ActionPopupBottomRow } from './action_popup_bottom_row'
import { ActionUsageScopeStore } from './action_usage_scope_store'
import { ActionRunDisabledMessage } from './action_run_disabled_message'
import { ActionRunHistoryOwner } from '../state/action_run_history_owner'
import { ActionRunInputStore } from '../state/action_run_input_store'
import { ActionRunResultStore } from '../state/action_run_result_store'
import { ActionRunStatusOwner } from '../state/action_run_status_owner'
import { ActionScheduleOwner } from '../schedule/action_schedule_owner'
import { ActionScheduleStore } from '../schedule/action_schedule_store'
import { ActionSelector } from './action_selector'
import { ActionWorktreeSelectorOwner } from './action_worktree_selector_owner'
import { MarkdownTypeaheadLayerProvider } from '../../../editor/markdown_typeahead_layer_provider'

export const CARD_RUN_POPUP_SIZE_STORAGE_KEY = 'md2.cardRunPopupSize'
export const PROJECT_AGENT_POPUP_SIZE_STORAGE_KEY = 'md2.projectAgentPopupSize'

interface ActionPopupBindings {
    conversationStore: ActionConversationStore
    historyStore: ActionHistoryStore
    inputStore: ActionRunInputStore
    resultStore: ActionRunResultStore
    scheduleStore: ActionScheduleStore
    usageScopeStore: ActionUsageScopeStore
}

function createActionPopupBindings(action: ActionDefinition, context: ActionContext): ActionPopupBindings {
    return {
        conversationStore: new ActionConversationStore(action.id, context),
        historyStore: new ActionHistoryStore(action, context),
        inputStore: new ActionRunInputStore(),
        resultStore: new ActionRunResultStore(),
        scheduleStore: new ActionScheduleStore(),
        usageScopeStore: new ActionUsageScopeStore(),
    }
}

interface ActionPopupContentProps {
    action: ActionDefinition
    actions: ActionDefinition[]
    anchorElement: HTMLElement | null
    assignmentContext: ActionContext
    baseContext: ActionContext
    draggable?: boolean
    fullHeight: boolean
    onActivate?: () => void
    onClose: () => void
    onSelectAction: (actionId: string) => void
    onToggleFullHeight: () => void
    open: boolean
    popupEntryId?: string
    primaryPath: string | null
    readOnlyMessage: string | null
    stackPosition?: number
    target: string | null
    titleId: string
}

/**
 * The message is rebuilt on every render but only reads the worktree list on the failing
 * path, so the popup never subscribes to worktree changes to keep a message it rarely shows.
 */
function worktreeValidationMessage(action: ActionDefinition, context: ActionContext) {
    const hasWorktreeAssignment = context.worktree !== undefined || !!context.worktreeError
    if (!hasWorktreeAssignment && !action.needsWorkTree) return null
    if (context.kind !== 'card' && context.kind !== 'project') {
        const reason = action.needsWorkTree ? 'when needsWorkTree is set' : 'for a worktree run'
        return `Action "${action.label}" requires card or project context ${reason}`
    }
    if (context.worktreeError) return context.worktreeError
    if (context.worktree === undefined) return `Action "${action.label}" requires a worktree assignment`
    if (!/^[1-9]\d*$/u.test(context.worktree)) return `Invalid worktree index: ${context.worktree}`

    const worktree = Number.parseInt(context.worktree, 10)
    if (!Number.isSafeInteger(worktree)) return `Invalid worktree index: ${context.worktree}`
    const record = worktreeService.getRecords()[worktree - 1]
    if (!record) return `Configured worktree ${worktree} does not exist`
    if (!record.valid) return `Configured worktree ${worktree} is invalid: ${record.error}`

    return null
}

function worktreeAssignmentTarget(context: ActionContext): WorktreeAssignmentTarget | null {
    if (context.kind === 'project') return { kind: 'project' }
    if ((context.kind === 'card' || context.kind === 'file') && context.file && context.cardInternalId) {
        return { cardInternalId: context.cardInternalId, kind: 'card', path: context.file }
    }

    return null
}

/** Presentation and run behavior for the internally selected popup action. */
export function ActionPopupContent(props: ActionPopupContentProps) {
    const {
        action, actions, anchorElement, assignmentContext, baseContext, draggable, fullHeight, onActivate,
        onClose, onSelectAction, onToggleFullHeight, open, primaryPath, stackPosition, target, titleId,
        popupEntryId, readOnlyMessage,
    } = props
    const theme = useTheme()
    const isMobile = useMediaQuery(theme.breakpoints.down('md'))
    const settingsContextIdentity = actionContextIdentity(assignmentContext)
    const settingsStore = useMemo(
        () => assignmentContext.cardInternalId
            ? actionRunSettingsService.getCardStore(assignmentContext.cardInternalId, action.id)
            : createSessionActionRunSettingsStore(action.id, settingsContextIdentity),
        [action.id, assignmentContext.cardInternalId, settingsContextIdentity],
    )
    const bindings = useMemo(
        () => createActionPopupBindings(action, assignmentContext),
        [action, assignmentContext],
    )
    const { conversationStore, historyStore, inputStore, resultStore, scheduleStore, usageScopeStore } = bindings
    const runValidationError = worktreeValidationMessage(action, assignmentContext)
    const sizeStorageKey = baseContext.kind === 'project'
        ? PROJECT_AGENT_POPUP_SIZE_STORAGE_KEY
        : CARD_RUN_POPUP_SIZE_STORAGE_KEY
    const parsedWorktree = assignmentContext.worktree && /^[1-9]\d*$/u.test(assignmentContext.worktree)
        ? Number.parseInt(assignmentContext.worktree, 10)
        : null
    const worktreeAssignment = {
        worktree: parsedWorktree,
        worktreeError: assignmentContext.worktreeError ?? null,
        worktreeValue: assignmentContext.worktree ?? null,
    }
    const assignmentTarget = baseContext.kind === 'card' || baseContext.kind === 'file' || baseContext.kind === 'project'
        ? worktreeAssignmentTarget(baseContext)
        : null
    return (
        <ResizablePopper
            anchorElement={anchorElement}
            draggable={isMobile ? false : draggable}
            fullHeight={isMobile || fullHeight}
            initialSize={{ height: 450, width: 400 }}
            labelId={titleId}
            onActivate={onActivate}
            onClose={onClose}
            open={open}
            paperSx={{
                bgcolor: 'background.paper',
                border: 1,
                borderColor: 'divider',
                borderRadius: isMobile ? 0 : '14px',
                boxShadow: '0 24px 60px rgba(16,24,40,0.28)',
                flexDirection: 'column',
                height: isMobile ? '100vh !important' : undefined,
                left: isMobile ? '0 !important' : undefined,
                margin: isMobile ? '0 !important' : undefined,
                maxHeight: isMobile ? 'none' : undefined,
                maxWidth: isMobile ? 'none' : undefined,
                top: isMobile ? '0 !important' : undefined,
                transform: isMobile ? 'none !important' : undefined,
                width: isMobile ? '100vw !important' : undefined,
            }}
            resizeFromAllSides
            resizeLabel="Resize action popup"
            stackPosition={stackPosition}
            storageKey={isMobile ? undefined : sizeStorageKey}
        >
            <MarkdownTypeaheadLayerProvider stackPosition={stackPosition ?? 0}>
                <Typography
                    id={titleId}
                    sx={{ clip: 'rect(0 0 0 0)', clipPath: 'inset(50%)', height: 1, overflow: 'hidden', position: 'absolute', whiteSpace: 'nowrap', width: 1 }}
                >
                    {target ? `Run actions for ${target}` : 'Run actions'}
                </Typography>
                <Box
                    data-drag-handle={!isMobile && draggable ? 'true' : undefined}
                    sx={{
                        borderBottom: 1, borderColor: 'divider', cursor: !isMobile && draggable ? 'move' : undefined,
                        display: 'flex', flexDirection: 'column', flexShrink: 0, gap: 1, px: 1.5, py: 1.5,
                    }}
                >
                    <Box data-testid="action-popup-toolbar" sx={{ alignItems: 'center', display: 'flex', gap: 1 }}>
                        {target ? (
                            <Box
                                component="span"
                                sx={{
                                    bgcolor: 'custom.primaryBg', borderRadius: '5px', color: 'primary.main', flexShrink: 0,
                                    fontFamily: '"Roboto Mono", ui-monospace, monospace', fontSize: 11.5, fontWeight: 600,
                                    px: 0.875, py: 0.25,
                                }}
                            >
                                {target}
                            </Box>
                        ) : null}
                        {assignmentTarget && !readOnlyMessage ? (
                            <ActionWorktreeSelectorOwner
                                actionId={action.id}
                                assignment={worktreeAssignment}
                                assignmentTarget={assignmentTarget}
                                context={assignmentContext}
                                primaryPath={primaryPath}
                            />
                        ) : null}
                        {action.type === 'agent' ? (
                            <ActionConversationPickerOwner
                                actionId={action.id}
                                context={assignmentContext}
                                store={conversationStore}
                            />
                        ) : null}
                        <Box sx={{ flex: 1 }} />
                        {!isMobile ? (
                            <Tooltip title={fullHeight ? 'Collapse downward' : 'Expand upward'}>
                                <IconButton
                                    aria-label={fullHeight ? 'Collapse downward' : 'Expand upward'}
                                    onClick={onToggleFullHeight}
                                    size="small"
                                    sx={{ flexShrink: 0, height: 30, width: 30 }}
                                >
                                    {fullHeight
                                        ? <ArrowCollapseVertical sx={{ fontSize: 18 }} />
                                        : <ArrowExpandVertical sx={{ fontSize: 18 }} />}
                                </IconButton>
                            </Tooltip>
                        ) : null}
                        <IconButton aria-label="Close" onClick={onClose} size="small" sx={{ flexShrink: 0, height: 30, width: 30 }}>
                            <Close sx={{ fontSize: 18 }} />
                        </IconButton>
                    </Box>
                    <ActionSelector
                        actions={actions}
                        context={assignmentContext}
                        onSelect={onSelectAction}
                        selectedAction={action}
                    />
                </Box>
                {readOnlyMessage ? (
                    <Stack data-testid="action-popup-scroll-body" spacing={2} sx={{ flex: 1, minHeight: 0, overflow: 'auto', px: 1.5, py: 1 }}>
                        {action.type === 'agent' ? (
                            <ActionConversationChatOwner
                                actionId={action.id}
                                context={assignmentContext}
                                popupEntryId={popupEntryId}
                                store={conversationStore}
                            />
                        ) : null}
                        <Typography color="text.secondary" role="note" variant="caption">{readOnlyMessage}</Typography>
                    </Stack>
                ) : <>
                    <Stack data-testid="action-popup-scroll-body" spacing={2} sx={{ flex: 1, minHeight: 0, overflow: 'auto', px: 1.5, py: 1 }}>
                        <ActionAgentInteractionVisibility action={action} context={assignmentContext}>
                            <Stack spacing={1} sx={{ flex: 1, minHeight: 0 }}>
                                <Box sx={{ alignItems: 'center', color: 'text.secondary', display: 'flex', flexWrap: 'wrap', fontSize: 12, gap: 0.75 }}>
                                    {action.type === 'agent' ? (
                                        <ActionAgentSelectorsOwner
                                            action={action}
                                            context={assignmentContext}
                                            settingsStore={settingsStore}
                                        />
                                    ) : null}
                                    <ActionLogErrorOwner actionId={action.id} context={assignmentContext} resultStore={resultStore} />
                                </Box>
                                <ActionConversationChatOwner
                                    actionId={action.id}
                                    context={assignmentContext}
                                    popupEntryId={popupEntryId}
                                    store={conversationStore}
                                />
                                <ActionAgentPromptOwner
                                    action={action}
                                    context={assignmentContext}
                                    conversationStore={conversationStore}
                                    historyStore={historyStore}
                                    inputStore={inputStore}
                                    settingsStore={settingsStore}
                                    resultStore={resultStore}
                                    runValidationError={runValidationError}
                                />
                                <ActionAgentApprovals actionId={action.id} context={assignmentContext} />
                                <ActionAgentQuestionOwner actionId={action.id} context={assignmentContext} />
                            </Stack>
                        </ActionAgentInteractionVisibility>
                        <ActionScheduleOwner action={action} context={baseContext} store={scheduleStore} />
                        {action.type !== 'agent' ? (
                            <ActionRunStatusOwner actionId={action.id} context={assignmentContext} resultStore={resultStore} />
                        ) : null}
                        <ActionRunDisabledMessage action={action} settingsStore={settingsStore} />
                        {runValidationError ? (
                            <Typography color="error.main" role="alert" variant="caption">
                                {runValidationError}
                            </Typography>
                        ) : null}
                        {action.type !== 'agent' ? (
                            <ActionRunHistoryOwner store={historyStore} />
                        ) : null}
                    </Stack>
                    <ActionPopupBottomRow
                        action={action}
                        assignmentContext={assignmentContext}
                        conversationStore={conversationStore}
                        historyStore={historyStore}
                        inputStore={inputStore}
                        settingsStore={settingsStore}
                        resultStore={resultStore}
                        runValidationError={runValidationError}
                        scheduleStore={scheduleStore}
                        usageScopeStore={usageScopeStore}
                    />
                </>}
            </MarkdownTypeaheadLayerProvider>
        </ResizablePopper>
    )
}

import { useId, useMemo, useState } from 'react'
import { displayActionsForContext, projectContextWithWorktree, type ActionContext } from '../../../../data/action_context'
import { dataService } from '../../../../services/data/data_service'
import { isReleasedCardActionContext, RELEASED_CARD_RUN_MESSAGE } from '../../../../../../shared/released_card_actions.mjs'
import { useActions } from '../../../hooks/use_actions'
import { useProjectState } from '../../../hooks/use_project_state'
import { useProjectActionWorktree } from '../../../hooks/use_worktrees'
import { ActionPopupContent } from './action_popup_content'

export { CARD_RUN_POPUP_SIZE_STORAGE_KEY, PROJECT_AGENT_POPUP_SIZE_STORAGE_KEY } from './action_popup_content'

function resolvePopupTarget(context: ActionContext, snapshot: ReturnType<typeof useProjectState>['snapshot']) {
    if (context.kind === 'project') return 'Project'
    if (context.kind !== 'card') return null

    const cards = [...(snapshot?.activeCards ?? []), ...(snapshot?.backgroundCards ?? [])]

    return cards.find(({ header }) => header.internalId === context.cardInternalId)?.header.id ?? null
}

interface ActionPopupProps {
    anchorElement: HTMLElement | null
    context: ActionContext
    draggable?: boolean
    initialActionId?: string
    onActivate?: () => void
    onClose: () => void
    open?: boolean
    popupEntryId?: string
    stackPosition?: number
}

/** Universal action selector and run popup for the supplied context. */
export function ActionPopup(props: ActionPopupProps) {
    const { anchorElement, context, initialActionId, open } = props
    const { actions: loadedActions } = useActions()
    const { project, snapshot } = useProjectState()
    const projectActionWorktree = useProjectActionWorktree()
    const effectiveContext = useMemo(
        () => projectContextWithWorktree(context, projectActionWorktree),
        [context, projectActionWorktree],
    )
    const actions = useMemo(() => displayActionsForContext(loadedActions, effectiveContext), [effectiveContext, loadedActions])
    const [selectedActionId, setSelectedActionId] = useState<string | null>(initialActionId ?? actions[0]?.id ?? null)
    const [fullHeight, setFullHeight] = useState(false)
    const titleId = useId()
    // A run that edits its own card changes the context (state, title, worktree), so the
    // selected action can drop out of the filtered list mid-run. Keep it selectable instead
    // of closing the popup or silently switching to another action.
    const retainedAction = selectedActionId ? loadedActions.find(({ id }) => id === selectedActionId) ?? null : null
    const selectedAction = actions.find(({ id }) => id === selectedActionId) ?? retainedAction ?? actions[0] ?? null
    const selectableActions = selectedAction && !actions.some(({ id }) => id === selectedAction.id)
        ? [...actions, selectedAction]
        : actions
    const target = resolvePopupTarget(context, snapshot)
    const releasesFolder = dataService.getConfig()?.releasesFolder
    const readOnlyMessage = releasesFolder && isReleasedCardActionContext(effectiveContext, releasesFolder)
        ? RELEASED_CARD_RUN_MESSAGE
        : null

    const handleSelectAction = (actionId: string) => {
        setSelectedActionId(actionId)
    }

    const handleToggleFullHeight = () => setFullHeight((current) => !current)

    if (!selectedAction) return null

    return (
        <ActionPopupContent
            {...props}
            action={selectedAction}
            actions={selectableActions}
            assignmentContext={effectiveContext}
            baseContext={context}
            fullHeight={fullHeight}
            onSelectAction={handleSelectAction}
            onToggleFullHeight={handleToggleFullHeight}
            open={open ?? !!anchorElement}
            primaryPath={project?.rootPath ?? project?.id ?? null}
            readOnlyMessage={readOnlyMessage}
            target={target}
            titleId={titleId}
        />
    )
}

import ArrowUpwardOutlined from '@mui/icons-material/ArrowUpwardOutlined'
import StopOutlined from '@mui/icons-material/StopOutlined'
import { Box, Button, IconButton, Tooltip } from '@mui/material'
import CalendarOutline from 'mdi-material-ui/CalendarOutline'
import Play from 'mdi-material-ui/Play'
import { useSyncExternalStore } from 'react'
import type { ActionContext } from '../../../../data/action_context'
import type { ActionDefinition } from '../../../../data/action_types'
import type { ActionRunSettingsStore } from '../../../../services/actions/action_run_settings_service'
import { useActionRunSelector } from '../../../hooks/use_action_runs'
import type { ActionConversationStore } from '../../conversation/action_conversation_store'
import type { ActionHistoryStore } from '../state/action_history_store'
import {
    cancelPopupAction,
    currentActionPromptDraft,
    finishPopupAction,
    runPopupAction,
} from './action_popup_operations'
import { actionPopupRunDisabled } from './action_popup_run_disabled'
import type { ActionRunInputStore } from '../state/action_run_input_store'
import type { ActionRunResultStore } from '../state/action_run_result_store'
import type { ActionScheduleStore } from '../schedule/action_schedule_store'
import { ActionUsageSummaryOwner } from './action_usage_summary_owner'
import { useActionRunSettings } from '../../shared/use_action_run_settings'
import { ActionPopupFinishButton } from './action_popup_finish_button'
import type { ActionUsageScopeStore } from './action_usage_scope_store'

interface ActionPopupBottomRowProps {
    action: ActionDefinition
    assignmentContext: ActionContext
    conversationStore: ActionConversationStore
    historyStore: ActionHistoryStore
    inputStore: ActionRunInputStore
    resultStore: ActionRunResultStore
    runValidationError: string | null
    scheduleStore: ActionScheduleStore
    settingsStore: ActionRunSettingsStore
    usageScopeStore: ActionUsageScopeStore
}

/** Run controls; subscribes only to run and prompt values used by this row. */
export function ActionPopupBottomRow(props: ActionPopupBottomRowProps) {
    const {
        action, assignmentContext, conversationStore, historyStore, inputStore, resultStore,
        runValidationError, scheduleStore, settingsStore, usageScopeStore,
    } = props
    const settings = useActionRunSettings(action, settingsStore)
    const runStatus = useActionRunSelector(action.id, assignmentContext, (run) => run?.status ?? 'idle')
    const agentActive = useActionRunSelector(action.id, assignmentContext, (run) => {
        const active = run?.status === 'queued' || run?.status === 'running' || run?.status === 'waitingForInput'

        return !!active && run?.activeActionType === 'agent'
    })
    const interactionReady = useActionRunSelector(action.id, assignmentContext, (run) => !!run?.interactionReady)
    const hasApprovals = useActionRunSelector(action.id, assignmentContext, (run) => !!run?.approvals.length)
    const hasQuestion = useActionRunSelector(action.id, assignmentContext, (run) => !!run?.question)
    const promptDraft = currentActionPromptDraft(action, assignmentContext, action.type === 'agent')
    const prompt = useSyncExternalStore(promptDraft.subscribe, promptDraft.getSnapshot, promptDraft.getSnapshot)
    const editorSnapshot = useSyncExternalStore(
        promptDraft.subscribeEditor,
        promptDraft.getEditorSnapshot,
        promptDraft.getEditorSnapshot,
    )
    const conversationSnapshot = useSyncExternalStore(
        conversationStore.subscribe,
        conversationStore.getSnapshot,
        conversationStore.getSnapshot,
    )
    const sessionActive = runStatus === 'queued' || runStatus === 'running' || runStatus === 'waitingForInput'
    const orphanWaiting = !sessionActive && conversationSnapshot.selectedConversation?.status === 'waitingForInput'
    const running = runStatus === 'queued' || runStatus === 'running'
    const waitingForAgentInput = (runStatus === 'waitingForInput' && agentActive) || orphanWaiting
    const promptHasText = prompt.trim().length > 0
    const showStop = running || (runStatus === 'waitingForInput' && !agentActive)
    const showFinish = waitingForAgentInput
    const showSchedule = (!sessionActive && !orphanWaiting) || (waitingForAgentInput && promptHasText)
    const showAgentSend = (!sessionActive && !orphanWaiting && action.type === 'agent')
        || (waitingForAgentInput && promptHasText)
    const showCommandRun = !sessionActive && !orphanWaiting && action.type === 'command'
    const runState = {
        agentActive,
        hasApprovals,
        hasQuestion,
        interactionReady,
        runDisabledMessage: settings.runDisabledMessage,
        runStatus,
    }
    const runDisabled = actionPopupRunDisabled(
        action,
        runState,
        prompt,
        editorSnapshot.preparationStatus,
    )
    const operationInput = {
        action,
        context: assignmentContext,
        conversationStore,
        historyStore,
        inputStore,
        resultStore,
        runValidationError,
        settings,
        settingsStore,
    }

    const handlePrimaryRun = async () => {
        await runPopupAction(operationInput)
    }
    const handleCancel = () => void cancelPopupAction(action, assignmentContext, conversationStore)
    const handleFinish = () => void finishPopupAction(action, assignmentContext, conversationStore)
    const handleToggleSchedule = () => scheduleStore.toggle()

    return (
        <Box sx={{ alignItems: 'center', bgcolor: 'background.default', borderTop: 1, borderColor: 'divider', display: 'flex', flexShrink: 0, gap: 1, px: 2, py: 1.5 }}>
            <ActionUsageSummaryOwner
                action={action}
                context={assignmentContext}
                conversationStore={conversationStore}
                historyStore={historyStore}
                scopeStore={usageScopeStore}
            />
            <Box sx={{ flex: 1 }} />
            {showFinish ? (
                <ActionPopupFinishButton
                    disabled={!settings.backendAvailable || (sessionActive && !interactionReady)}
                    onFinish={handleFinish}
                    onStop={handleCancel}
                />
            ) : null}
            {showSchedule ? (
                <Tooltip title="Schedule">
                    <span>
                        <IconButton
                            aria-label="Schedule"
                            disabled={!settings.backendAvailable}
                            onClick={handleToggleSchedule}
                            size="small"
                        >
                            <CalendarOutline sx={{ fontSize: 18 }} />
                        </IconButton>
                    </span>
                </Tooltip>
            ) : null}
            {showAgentSend ? (
                <Tooltip title="Send">
                    <span>
                        <IconButton aria-label="Send" color="primary" disabled={runDisabled} onClick={handlePrimaryRun} size="small">
                            <ArrowUpwardOutlined sx={{ fontSize: 18 }} />
                        </IconButton>
                    </span>
                </Tooltip>
            ) : showCommandRun ? (
                <Tooltip title="Run">
                    <Button
                        disabled={runDisabled}
                        onClick={handlePrimaryRun}
                        size="small"
                        startIcon={<Play sx={{ fontSize: '13px !important' }} />}
                        sx={{ height: 34, px: 2 }}
                        variant="contained"
                    >
                        Run
                    </Button>
                </Tooltip>
            ) : showStop ? (
                <Tooltip title="Stop">
                    <span>
                        <IconButton aria-label="Stop" disabled={!settings.backendAvailable} onClick={handleCancel} size="small">
                            <StopOutlined sx={{ fontSize: 18 }} />
                        </IconButton>
                    </span>
                </Tooltip>
            ) : null}
        </Box>
    )
}

