import { Box, Typography } from '@mui/material'
import {
    useEffect, useRef, useState, useSyncExternalStore, type KeyboardEvent, type PointerEvent as ReactPointerEvent, type ReactNode,
} from 'react'
import { ACTION_PROMPT_PLACEHOLDERS } from '../../../data/action_placeholders'
import { dialogService } from '../../../services/dialog_service'
import type { ActionPromptDraft } from '../../../services/actions/action_prompt_draft_service'
import { MarkdownEditor, type MarkdownEditorHandle } from '../../editor/markdown_editor'

const MIN_PROMPT_HEIGHT = 72
const MIN_CHAT_HEIGHT = 96
const DEFAULT_PROMPT_HEIGHT = 140
const PROMPT_RESIZE_STEP = 24
const PROMPT_HEIGHT_STORAGE_KEY = 'md2.actionPromptHeight'

function readStoredPromptHeight(): number {
    const storedValue = window.localStorage.getItem(PROMPT_HEIGHT_STORAGE_KEY)
    const parsedValue = storedValue ? Number.parseInt(storedValue, 10) : Number.NaN

    return Number.isNaN(parsedValue) ? DEFAULT_PROMPT_HEIGHT : parsedValue
}

interface ActionAgentPromptProps {
    convertMessage: string | null
    disabled: boolean
    onRunShortcut?: () => void
    promptDraft: ActionPromptDraft
    responsePrompts?: ReactNode
}

/** Resizable prompt editor shown below an agent conversation. */
export function ActionAgentPrompt(props: ActionAgentPromptProps) {
    const {convertMessage, disabled, onRunShortcut, promptDraft, responsePrompts} = props
    const promptEditorRef = useRef<MarkdownEditorHandle>(null)
    const promptHeightStartRef = useRef(0)
    const pointerStartYRef = useRef(0)
    const splitContainerRef = useRef<HTMLElement | null>(null)
    const [promptHeight, setPromptHeight] = useState(readStoredPromptHeight)
    const [resizingPrompt, setResizingPrompt] = useState(false)
    const editorSnapshot = useSyncExternalStore(
        promptDraft.subscribeEditor,
        promptDraft.getEditorSnapshot,
        promptDraft.getEditorSnapshot,
    )

    useEffect(() => {
        promptEditorRef.current?.setMarkdown(promptDraft.getSnapshot())
    }, [editorSnapshot.replacementRevision, promptDraft])

    const handlePromptChange = (value: string) => {
        promptDraft.edit(value)
        void promptDraft.synchronize().catch((error: unknown) => {
            dialogService.error(error, { fallbackMessage: 'Could not queue agent prompt' })
        })
    }

    const clampPromptHeight = (proposed: number) => {
        const container = splitContainerRef.current
        const available = container ? container.getBoundingClientRect().height - MIN_CHAT_HEIGHT : proposed
        const max = Math.max(MIN_PROMPT_HEIGHT, available)

        return Math.min(Math.max(proposed, MIN_PROMPT_HEIGHT), max)
    }

    const persistPromptHeight = (height: number) => {
        window.localStorage.setItem(PROMPT_HEIGHT_STORAGE_KEY, String(Math.round(height)))
    }

    const handleSplitPointerDown = (event: ReactPointerEvent<HTMLDivElement>) => {
        event.preventDefault()
        splitContainerRef.current = event.currentTarget.parentElement
        promptHeightStartRef.current = promptHeight
        pointerStartYRef.current = event.clientY
        setResizingPrompt(true)
        event.currentTarget.setPointerCapture?.(event.pointerId)
    }

    const handleSplitPointerMove = (event: ReactPointerEvent<HTMLDivElement>) => {
        if (!resizingPrompt) return

        const delta = pointerStartYRef.current - event.clientY
        setPromptHeight(clampPromptHeight(promptHeightStartRef.current + delta))
    }

    const handleSplitPointerUp = (event: ReactPointerEvent<HTMLDivElement>) => {
        if (!resizingPrompt) return

        setResizingPrompt(false)
        event.currentTarget.releasePointerCapture?.(event.pointerId)
        setPromptHeight((height) => {
            persistPromptHeight(height)

            return height
        })
    }

    const handleSplitKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
        splitContainerRef.current = event.currentTarget.parentElement
        const nextByKey: Record<string, number> = {
            ArrowDown: promptHeight - PROMPT_RESIZE_STEP,
            ArrowUp: promptHeight + PROMPT_RESIZE_STEP,
        }
        const next = nextByKey[event.key]
        if (next === undefined) return

        event.preventDefault()
        const clamped = clampPromptHeight(next)
        setPromptHeight(clamped)
        persistPromptHeight(clamped)
    }

    const handlePromptKeyDownCapture = (event: KeyboardEvent<HTMLDivElement>) => {
        if (event.key !== 'Enter' || (!event.ctrlKey && !event.metaKey) || !onRunShortcut) return

        event.preventDefault()
        event.stopPropagation()
        promptEditorRef.current?.flush()
        onRunShortcut()
    }

    return (
        <>
            <Box
                aria-label="Resize prompt"
                aria-orientation="horizontal"
                aria-valuemin={MIN_PROMPT_HEIGHT}
                aria-valuenow={Math.round(promptHeight)}
                onKeyDown={handleSplitKeyDown}
                onPointerDown={handleSplitPointerDown}
                onPointerMove={handleSplitPointerMove}
                onPointerUp={handleSplitPointerUp}
                role="separator"
                sx={{
                    bgcolor: resizingPrompt ? 'primary.main' : 'divider',
                    borderRadius: '2px',
                    cursor: 'row-resize',
                    flexShrink: 0,
                    height: '3px',
                    mx: 'auto',
                    my: '2px',
                    width: '100%',
                    '&:hover': { bgcolor: 'primary.main' },
                }}
                tabIndex={0}
            />
            <Box
                aria-label="Prompt"
                onKeyDownCapture={handlePromptKeyDownCapture}
                sx={{
                    borderRadius: '9px',
                    border: 1,
                    borderColor: 'custom.borderStrong',
                    display: 'flex',
                    flexDirection: 'column',
                    flexShrink: 0,
                    height: promptHeight,
                    overflow: 'hidden',
                    '&:focus-within': {
                        borderColor: 'primary.main',
                        boxShadow: (theme) => `0 0 0 3px ${theme.palette.action.selected}`,
                    },
                }}
            >
                <Box sx={{ flex: 1, minHeight: 0, overflowY: 'auto', px: 1 }}>
                    <MarkdownEditor
                        flushOnBlur
                        hideToolbar
                        markdown={promptDraft.getSnapshot()}
                        onChange={handlePromptChange}
                        onLiveChange={promptDraft.edit}
                        placeholders={ACTION_PROMPT_PLACEHOLDERS}
                        readOnly={disabled || editorSnapshot.preparationStatus !== 'ready'}
                        ref={promptEditorRef}
                    />
                </Box>
                {responsePrompts}
            </Box>
            {convertMessage ? (
                <Typography color="text.secondary" role="status" variant="caption">
                    {convertMessage}
                </Typography>
            ) : null}
        </>
    )
}

import { act, cleanup, fireEvent, render, screen } from '@testing-library/react'
import { afterEach, describe, expect, it, vi } from 'vitest'
import { ActionAgentPrompt } from './action_agent_prompt'
import { ACTION_PROMPT_PLACEHOLDERS } from '../../../data/action_placeholders'
import { ActionPromptDraft } from '../../../services/actions/action_prompt_draft_service'

const setMarkdown = vi.hoisted(() => vi.fn())

vi.mock('../../editor/markdown_editor', async () => {
    const { forwardRef, useImperativeHandle, useRef, useState } = await import('react')

    return {
        MarkdownEditor: forwardRef(function MarkdownEditorMock(props: {
            flushOnBlur?: boolean
            markdown: string
            onChange: (markdown: string) => void
            onLiveChange?: (markdown: string) => void
            placeholders?: readonly { name: string }[]
            readOnly?: boolean
        }, ref) {
            const valueRef = useRef(props.markdown)
            const [value, setValue] = useState(props.markdown)
            useImperativeHandle(ref, () => ({
                flush: () => {
                    props.onChange(valueRef.current)

                    return true
                },
                getMarkdown: () => valueRef.current,
                setMarkdown: (markdown: string) => {
                    valueRef.current = markdown
                    setValue(markdown)
                    setMarkdown(markdown)
                },
            }))

            return (
                <textarea
                    aria-label="Markdown prompt"
                    data-flush-on-blur={props.flushOnBlur ? 'true' : 'false'}
                    data-placeholders={props.placeholders?.map(({ name }) => name).join(',')}
                    value={value}
                    onBlur={(event) => props.onChange(event.currentTarget.value)}
                    onChange={(event) => {
                        valueRef.current = event.currentTarget.value
                        setValue(event.currentTarget.value)
                        props.onLiveChange?.(event.currentTarget.value)
                    }}
                    onKeyDown={(event) => {
                        if (event.key !== 'Enter') return

                        const nextValue = `${valueRef.current}\n`
                        valueRef.current = nextValue
                        setValue(nextValue)
                        props.onLiveChange?.(nextValue)
                    }}
                    readOnly={props.readOnly}
                />
            )
        }),
    }
})

afterEach(cleanup)

describe('ActionAgentPrompt', () => {
    it('configures action placeholders on its hidden-toolbar editor', () => {
        const promptDraft = new ActionPromptDraft('', false, null)
        render(
            <ActionAgentPrompt
                convertMessage={null}
                disabled={false}
                promptDraft={promptDraft}
            />,
        )

        expect(screen.getByLabelText('Markdown prompt')).toHaveAttribute(
            'data-placeholders',
            ACTION_PROMPT_PLACEHOLDERS.map(({ name }) => name).join(','),
        )
        expect(screen.getByLabelText('Markdown prompt').getAttribute('data-placeholders')).toContain('this-card')
    })

    it('keeps typing local and synchronizes the prompt on blur', () => {
        const promptDraft = new ActionPromptDraft('', false, null)
        const synchronize = vi.spyOn(promptDraft, 'synchronize')
        render(
            <ActionAgentPrompt
                convertMessage={null}
                disabled={false}
                promptDraft={promptDraft}
            />,
        )
        const prompt = screen.getByLabelText('Markdown prompt')

        fireEvent.change(prompt, { target: { value: 'Draft' } })

        expect(synchronize).not.toHaveBeenCalled()
        expect(promptDraft.getSnapshot()).toBe('Draft')
        expect(prompt).toHaveAttribute('data-flush-on-blur', 'true')

        fireEvent.blur(prompt)

        expect(synchronize).toHaveBeenCalledOnce()
    })

    it.each([
        { keyModifier: { ctrlKey: true }, shortcut: 'Ctrl+Enter' },
        { keyModifier: { metaKey: true }, shortcut: 'Meta+Enter' },
    ])('flushes the latest prompt before running $shortcut without passing it to the editor', ({ keyModifier }) => {
        const handleRunShortcut = vi.fn()
        const promptDraft = new ActionPromptDraft('', false, null)
        const synchronize = vi.spyOn(promptDraft, 'synchronize')
        render(
            <ActionAgentPrompt
                convertMessage={null}
                disabled={false}
                onRunShortcut={handleRunShortcut}
                promptDraft={promptDraft}
            />,
        )
        const prompt = screen.getByLabelText('Markdown prompt')

        fireEvent.change(prompt, { target: { value: 'Run this' } })
        fireEvent.keyDown(prompt, { ...keyModifier, key: 'Enter' })

        expect(synchronize).toHaveBeenCalledOnce()
        expect(synchronize.mock.invocationCallOrder[0]).toBeLessThan(handleRunShortcut.mock.invocationCallOrder[0])
        expect(handleRunShortcut).toHaveBeenCalledOnce()
        expect(promptDraft.getSnapshot()).toBe('Run this')
        expect(prompt).toHaveValue('Run this')
    })

    it('keeps plain Enter and Shift+Enter editor behavior', () => {
        const promptDraft = new ActionPromptDraft('Line', false, null)
        render(
            <ActionAgentPrompt
                convertMessage={null}
                disabled={false}
                onRunShortcut={vi.fn()}
                promptDraft={promptDraft}
            />,
        )
        const prompt = screen.getByLabelText('Markdown prompt')

        fireEvent.keyDown(prompt, { key: 'Enter' })
        fireEvent.keyDown(prompt, { key: 'Enter', shiftKey: true })

        expect(promptDraft.getSnapshot()).toBe('Line\n\n')
        expect(prompt).toHaveValue('Line\n\n')
    })

    it('keeps Ctrl+Enter editor behavior when no shortcut callback exists', () => {
        const promptDraft = new ActionPromptDraft('Line', false, null)
        render(
            <ActionAgentPrompt
                convertMessage={null}
                disabled={false}
                promptDraft={promptDraft}
            />,
        )
        const prompt = screen.getByLabelText('Markdown prompt')

        fireEvent.keyDown(prompt, { ctrlKey: true, key: 'Enter' })

        expect(promptDraft.getSnapshot()).toBe('Line\n')
        expect(prompt).toHaveValue('Line\n')
    })

    it('applies each external replacement to the mounted editor once', () => {
        const promptDraft = new ActionPromptDraft('Initial', false, null)
        render(
            <ActionAgentPrompt
                convertMessage={null}
                disabled={false}
                promptDraft={promptDraft}
            />,
        )
        setMarkdown.mockClear()

        act(() => promptDraft.replace('Prepared'))

        expect(setMarkdown).toHaveBeenCalledOnce()
        expect(setMarkdown).toHaveBeenCalledWith('Prepared')
        expect(screen.getByLabelText('Markdown prompt')).toHaveValue('Prepared')
    })
})

